INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('49c8fe17-3bc2-532e-a2e0-e689c395410c'::uuid, '49761da5-b40c-5a1a-a798-3c42a7f4af9b'::uuid, 'CHAUFFE-EAU SOLAIRE WESTMANN', 'Chauffe-eau Solaire WESTMANN – Spécial Pro BTP & Projets Haut de Gamme, conçu pour les professionnels du bâtiment, architectes et projets exigeants au Maroc.', 'Solar energy', NULL, NULL, 12000.0, 'MAD', 'm²', '5 Pièce', 'https://lechantier.ma/uploads/media/7e59c852cf87.webp', $j$["https://lechantier.ma/uploads/media/7e59c852cf87.webp", "https://lechantier.ma/uploads/media/1f518d9b08c1.webp"]$j$::jsonb, $j$["Marrakech"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/energie-solaire/chauffe-eau-solaire-westmann", "category_fr": "Climatisation / Chauffage", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Cuve en Inox 316L : qualité supérieure, ultra résistante à la corrosion📦 Capacités disponibles : 200L / 300L / 500L♻️ Système à circuit fermé : sécurité renforcée, adapté aux eaux dures et régions chaudes☀️ Capteurs plans haute performance avec verre trempé et structure aluminium🧊 Isolation thermique haute densité – conserve l’eau chaude jusqu’à 72h🔧 Châssis en aluminium : anticorrosion, longue durée de vie🔒 Sans entretien – conçu pour fonctionner de façon autonome pendant des années🛡️ Garantie fabricant : 10 ans", "technical_specifications_original": "• Cuve en Inox 316L : qualité supérieure, ultra résistante à la corrosion📦 Capacités disponibles : 200L / 300L / 500L♻️ Système à circuit fermé : sécurité renforcée, adapté aux eaux dures et régions chaudes☀️ Capteurs plans haute performance avec verre trempé et structure aluminium🧊 Isolation thermique haute densité – conserve l’eau chaude jusqu’à 72h🔧 Châssis en aluminium : anticorrosion, longue durée de vie🔒 Sans entretien – conçu pour fonctionner de façon autonome pendant des années🛡️ Garantie fabricant : 10 ans", "specs": "• Cuve en Inox 316L : qualité supérieure, ultra résistante à la corrosion📦 Capacités disponibles : 200L / 300L / 500L♻️ Système à circuit fermé : sécurité renforcée, adapté aux eaux dures et régions chaudes☀️ Capteurs plans haute performance avec verre trempé et structure aluminium🧊 Isolation thermique haute densité – conserve l’eau chaude jusqu’à 72h🔧 Châssis en aluminium : anticorrosion, longue durée de vie🔒 Sans entretien – conçu pour fonctionner de façon autonome pendant des années🛡️ Garantie fabricant : 10 ans"}$j$::jsonb, 'https://lechantier.ma/en/produits/energie-solaire/chauffe-eau-solaire-westmann') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('32ce7cd6-aa76-5457-8373-b376bf09966d'::uuid, 'b35c08a2-b5db-53c7-925f-f60f5abaf4da'::uuid, 'Diagnostic de Consommation Électrique', 'Service d''analyse personnalisé de votre consommation électrique pour identifier les sources de gaspillage et étudier la faisabilité d''une installation solaire adaptée.', 'Solar energy', NULL, NULL, 900.0, 'MAD', 'Lot', '1 Lot', 'https://lechantier.ma/uploads/media/4c8f4b097647.webp', $j$["https://lechantier.ma/uploads/media/4c8f4b097647.webp", "https://lechantier.ma/uploads/media/9728c72348a2.webp"]$j$::jsonb, $j$["Rabat"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/energie-solaire/diagnostic-de-consommation-electrique", "category_fr": "Climatisation / Chauffage", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Nous installons un analyseur de charge directement sur votre tableau électrique pour une durée minimale de 7 jours afin de mesurer en temps réel votre consommation d’électricité.L’appareil enregistre des données détaillées par phase (puissance instantanée, énergie active/réactive, tension, intensité, facteur de puissance, etc.), ce qui permet de :Étudier le profil de charge sur 24h et par jour de la semaineIdentifier les pics de consommation, les appareils énergivores et les consommations cachées (en veille)Repérer les anomalies éventuelles (déséquilibre entre phases, consommation de nuit anormale…)Proposer des recommandations d’optimisation adaptées à vos habitudesFournir une simulation de production solaire en autoconsommation et une estimation des économies réalisablesLes données sont ensuite analysées par nos experts et restituées sous forme d’un rapport clair et illustré, accompagné de conseils personnalisés.", "technical_specifications_original": "• Nous installons un analyseur de charge directement sur votre tableau électrique pour une durée minimale de 7 jours afin de mesurer en temps réel votre consommation d’électricité.L’appareil enregistre des données détaillées par phase (puissance instantanée, énergie active/réactive, tension, intensité, facteur de puissance, etc.), ce qui permet de :Étudier le profil de charge sur 24h et par jour de la semaineIdentifier les pics de consommation, les appareils énergivores et les consommations cachées (en veille)Repérer les anomalies éventuelles (déséquilibre entre phases, consommation de nuit anormale…)Proposer des recommandations d’optimisation adaptées à vos habitudesFournir une simulation de production solaire en autoconsommation et une estimation des économies réalisablesLes données sont ensuite analysées par nos experts et restituées sous forme d’un rapport clair et illustré, accompagné de conseils personnalisés.", "specs": "• Nous installons un analyseur de charge directement sur votre tableau électrique pour une durée minimale de 7 jours afin de mesurer en temps réel votre consommation d’électricité.L’appareil enregistre des données détaillées par phase (puissance instantanée, énergie active/réactive, tension, intensité, facteur de puissance, etc.), ce qui permet de :Étudier le profil de charge sur 24h et par jour de la semaineIdentifier les pics de consommation, les appareils énergivores et les consommations cachées (en veille)Repérer les anomalies éventuelles (déséquilibre entre phases, consommation de nuit anormale…)Proposer des recommandations d’optimisation adaptées à vos habitudesFournir une simulation de production solaire en autoconsommation et une estimation des économies réalisablesLes données sont ensuite analysées par nos experts et restituées sous forme d’un rapport clair et illustré, accompagné de conseils personnalisés."}$j$::jsonb, 'https://lechantier.ma/en/produits/energie-solaire/diagnostic-de-consommation-electrique') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
