INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('5b6a6a91-0159-5437-a15a-35f1b5dab65d'::uuid, 'c83df0de-cf2b-5b71-b40c-11d7f849ded3'::uuid, 'Panneaux solare Canadien solar 620 Wc', 'PANNEAU SOLAIRE BIFACIAL 620Wc CANADIAN SOLAR', 'Solar energy', NULL, NULL, 900.0, 'MAD', 'Pièce', '1 Pièce', 'https://lechantier.ma/uploads/media/1d76c5afa283.webp', $j$["https://lechantier.ma/uploads/media/1d76c5afa283.webp"]$j$::jsonb, $j$[]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/energie-solaire/panneaux-solare-canadien-solar-620-wc", "category_fr": "Climatisation / Chauffage", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Le panneau solaire bifacial Canadian Solar 620 Wc est un module photovoltaïque de haute performance, équipé de la technologie avancée N-type TOPCon qui lui confère un rendement exceptionnel de 23 %. Sa conception bifaciale lui permet de capter la lumière sur ses deux faces, générant jusqu’à 80 % d’énergie supplémentaire via l’arrière et améliorant ainsi le rendement global de l’installation.Avec une puissance nominale de 620 Wc, ce panneau est particulièrement adapté aux projets industriels, commerciaux et aux centrales photovoltaïques de grande échelle, permettant de réduire efficacement le coût nivelé de l’énergie (LCOE) tout en garantissant une durée de vie prolongée et une fiabilité éprouvée.Spécifications techniquesCaractéristiques électriques (STC)Puissance maximale (Pmax) : 620 WcTension au point de puissance maximale (Vmp) : 41,2 VCourant au point de puissance maximale (Imp) : 15,06 ATension à vide (Voc) : 48,4 VCourant de court-circuit (Isc) : 16,08 ARendement du module : 23 %Caractéristiques mécaniquesDimensions : 2382 × 1134 × 30 mmPoids : 33,6 kgFace avant : verre trempé 2 mm avec traitement anti-refletFace arrière : verre trempé 2 mmCadre : aluminium anodiséConditions d’utilisationTempérature de fonctionnement : -40°C à +85°CTension système maximale : 1500 V (IEC/UL)Atouts du panneau bifacial Canadian Solar 620 WcRendement énergétique supérieur grâce à la technologie N-type TOPConProduction accrue grâce à l’effet bifacialConçu pour résister aux environnements difficiles et assurer une fiabilité à long termeGarantie étendue et faible taux de dégradation, garantissant un investissement sûr et durable", "technical_specifications_original": "• Le panneau solaire bifacial Canadian Solar 620 Wc est un module photovoltaïque de haute performance, équipé de la technologie avancée N-type TOPCon qui lui confère un rendement exceptionnel de 23 %. Sa conception bifaciale lui permet de capter la lumière sur ses deux faces, générant jusqu’à 80 % d’énergie supplémentaire via l’arrière et améliorant ainsi le rendement global de l’installation.Avec une puissance nominale de 620 Wc, ce panneau est particulièrement adapté aux projets industriels, commerciaux et aux centrales photovoltaïques de grande échelle, permettant de réduire efficacement le coût nivelé de l’énergie (LCOE) tout en garantissant une durée de vie prolongée et une fiabilité éprouvée.Spécifications techniquesCaractéristiques électriques (STC)Puissance maximale (Pmax) : 620 WcTension au point de puissance maximale (Vmp) : 41,2 VCourant au point de puissance maximale (Imp) : 15,06 ATension à vide (Voc) : 48,4 VCourant de court-circuit (Isc) : 16,08 ARendement du module : 23 %Caractéristiques mécaniquesDimensions : 2382 × 1134 × 30 mmPoids : 33,6 kgFace avant : verre trempé 2 mm avec traitement anti-refletFace arrière : verre trempé 2 mmCadre : aluminium anodiséConditions d’utilisationTempérature de fonctionnement : -40°C à +85°CTension système maximale : 1500 V (IEC/UL)Atouts du panneau bifacial Canadian Solar 620 WcRendement énergétique supérieur grâce à la technologie N-type TOPConProduction accrue grâce à l’effet bifacialConçu pour résister aux environnements difficiles et assurer une fiabilité à long termeGarantie étendue et faible taux de dégradation, garantissant un investissement sûr et durable", "specs": "• Le panneau solaire bifacial Canadian Solar 620 Wc est un module photovoltaïque de haute performance, équipé de la technologie avancée N-type TOPCon qui lui confère un rendement exceptionnel de 23 %. Sa conception bifaciale lui permet de capter la lumière sur ses deux faces, générant jusqu’à 80 % d’énergie supplémentaire via l’arrière et améliorant ainsi le rendement global de l’installation.Avec une puissance nominale de 620 Wc, ce panneau est particulièrement adapté aux projets industriels, commerciaux et aux centrales photovoltaïques de grande échelle, permettant de réduire efficacement le coût nivelé de l’énergie (LCOE) tout en garantissant une durée de vie prolongée et une fiabilité éprouvée.Spécifications techniquesCaractéristiques électriques (STC)Puissance maximale (Pmax) : 620 WcTension au point de puissance maximale (Vmp) : 41,2 VCourant au point de puissance maximale (Imp) : 15,06 ATension à vide (Voc) : 48,4 VCourant de court-circuit (Isc) : 16,08 ARendement du module : 23 %Caractéristiques mécaniquesDimensions : 2382 × 1134 × 30 mmPoids : 33,6 kgFace avant : verre trempé 2 mm avec traitement anti-refletFace arrière : verre trempé 2 mmCadre : aluminium anodiséConditions d’utilisationTempérature de fonctionnement : -40°C à +85°CTension système maximale : 1500 V (IEC/UL)Atouts du panneau bifacial Canadian Solar 620 WcRendement énergétique supérieur grâce à la technologie N-type TOPConProduction accrue grâce à l’effet bifacialConçu pour résister aux environnements difficiles et assurer une fiabilité à long termeGarantie étendue et faible taux de dégradation, garantissant un investissement sûr et durable"}$j$::jsonb, 'https://lechantier.ma/en/produits/energie-solaire/panneaux-solare-canadien-solar-620-wc') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, 