INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('f875310f-2222-5d78-b1e6-51ae2cd802e8'::uuid, '01ee9428-38a2-5728-9fea-45675b1b219b'::uuid, 'Projecteur LED SOLTEK', 'Les projecteurs solaires LED de la gamme « SOLTEK » 100W PRIX 480DH 200W PRIX 650DH 300W PRIX 850DH', 'Solar energy', NULL, NULL, 450.0, 'MAD', 'm²', '1 Pièce', 'https://lechantier.ma/uploads/media/090f642623c3.webp', $j$["https://lechantier.ma/uploads/media/090f642623c3.webp", "https://lechantier.ma/uploads/media/a2201723d368.webp", "https://lechantier.ma/uploads/media/0bafabec4245.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/energie-solaire/projecteur-led-soltek", "category_fr": "Climatisation / Chauffage", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Les projecteurs solaires LED de la gamme « SOLTEK » créent un point d’éclairage là où le réseau électrique n’est pas disponible, grâce à leur panneau solaire et leur batterie intégrée. Ces projecteurs peuvent s’allumer automatiquement et assurer ainsi un éclairage continu qui doit durer du coucher au lever du soleil. Ces luminaires sont destinés à assurer un éclairage d’extérieur dans les maisons rurales, chantiers de construction, jardins des maisons, parcs, cours ou voies publiques etc.", "technical_specifications_original": "• Les projecteurs solaires LED de la gamme « SOLTEK » créent un point d’éclairage là où le réseau électrique n’est pas disponible, grâce à leur panneau solaire et leur batterie intégrée. Ces projecteurs peuvent s’allumer automatiquement et assurer ainsi un éclairage continu qui doit durer du coucher au lever du soleil. Ces luminaires sont destinés à assurer un éclairage d’extérieur dans les maisons rurales, chantiers de construction, jardins des maisons, parcs, cours ou voies publiques etc.", "specs": "• Les projecteurs solaires LED de la gamme « SOLTEK » créent un point d’éclairage là où le réseau électrique n’est pas disponible, grâce à leur panneau solaire et leur batterie intégrée. Ces projecteurs peuvent s’allumer automatiquement et assurer ainsi un éclairage continu qui doit durer du coucher au lever du soleil. Ces luminaires sont destinés à assurer un éclairage d’extérieur dans les maisons rurales, chantiers de construction, jardins des maisons, parcs, cours ou voies publiques etc."}$j$::jsonb, 'https://lechantier.ma/en/produits/energie-solaire/projecteur-led-soltek') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
