INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('bfb9bc94-8721-5cd5-8efb-c9e72f25c8b9'::uuid, '5357c4b9-08a3-54e5-86d0-f6a3eb7496a1'::uuid, 'papier hygiénique', 'Notre papier hygiénique se distingue par sa douceur, sa résistance et son pouvoir absorbant élevé, garantissant un confort optimal et une hygiène irréprochable.', 'Other', NULL, NULL, 10.0, 'MAD', 'm²', '1 KG', 'https://lechantier.ma/uploads/media/d0845a2c2fae.webp', $j$["https://lechantier.ma/uploads/media/d0845a2c2fae.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/epi-autres/papier-hygienique", "category_fr": "Matériaux de construction", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Disponible en plusieurs formats (simple, double ou triple épaisseur), il s’intègre parfaitement dans nos solutions complètes d’entretien et d’hygiène professionnelle.\n• Produit respectueux de l’environnement\n• Texture douce et résistante\n• Idéal pour une utilisation quotidienne dans les espaces à forte fréquentation", "technical_specifications_original": "• Disponible en plusieurs formats (simple, double ou triple épaisseur), il s’intègre parfaitement dans nos solutions complètes d’entretien et d’hygiène professionnelle.\n• Produit respectueux de l’environnement\n• Texture douce et résistante\n• Idéal pour une utilisation quotidienne dans les espaces à forte fréquentation", "specs": "• Disponible en plusieurs formats (simple, double ou triple épaisseur), il s’intègre parfaitement dans nos solutions complètes d’entretien et d’hygiène professionnelle.\n• Produit respectueux de l’environnement\n• Texture douce et résistante\n• Idéal pour une utilisation quotidienne dans les espaces à forte fréquentation"}$j$::jsonb, 'https://lechantier.ma/en/produits/epi-autres/papier-hygienique') ON