INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('d6848001-46d2-538b-9c32-a402b3f6622e'::uuid, '9905df39-f4ef-5a6f-ab9d-9ff7371412a6'::uuid, 'BARRIERE MOSAIQUE', 'Le barriére Mosaique est un élément de mobilier urbain alliant esthétique moderne et robustesse industrielle. Concue en acier galavanisé et protégée par une peinture thérmolaquée.', 'Other', NULL, NULL, 600.0, 'MAD', 'm²', '10 Pièce', 'https://lechantier.ma/uploads/media/ee07ee22fbf1.webp', $j$["https://lechantier.ma/uploads/media/ee07ee22fbf1.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/ferronnerie-metallurgie-autres/barriere-mosaique", "category_fr": "Matériaux de construction", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Dénomination : Barrière MosaïqueUsage : Mobilier urbain / Sécurisation de zones piétonnes et espaces publicsMatériau principal : Acier galvanisé à chaudFinition : Peinture thermolaquée couleur gris métallisé (autres teintes RAL sur demande)Dimensions standards : Longueur : 3000 mm – Hauteur : 1200 mmSystème de fixation: Sur platine avec ancrage mécanique ou scellement direct dans le solPersonnalisation possible : Dimensions, motifs, teintes RAL, logo ou design spécifique", "technical_specifications_original": "• Dénomination : Barrière MosaïqueUsage : Mobilier urbain / Sécurisation de zones piétonnes et espaces publicsMatériau principal : Acier galvanisé à chaudFinition : Peinture thermolaquée couleur gris métallisé (autres teintes RAL sur demande)Dimensions standards : Longueur : 3000 mm – Hauteur : 1200 mmSystème de fixation: Sur platine avec ancrage mécanique ou scellement direct dans le solPersonnalisation possible : Dimensions, motifs, teintes RAL, logo ou design spécifique", "specs": "• Dénomination : Barrière MosaïqueUsage : Mobilier urbain / Sécurisation de zones piétonnes et espaces publicsMatériau principal : Acier galvanisé à chaudFinition : Peinture thermolaquée couleur gris métallisé (autres teintes RAL sur demande)Dimensions standards : Longueur : 3000 mm – Hauteur : 1200 mmSystème de fixation: Sur platine avec ancrage mécanique ou scellement direct dans le solPersonnalisation possible : Dimensions, motifs, teintes RAL, logo ou design spécifique"}$j$::jsonb, 'https://lechantier.ma/en/produits/ferronnerie-metallurgie-autres/barriere-mosaique') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
