INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('6186c821-1bc1-5171-9721-a5acab23ca8a'::uuid, '6599950d-415c-50aa-93b2-8aeafc7febbc'::uuid, 'Tole en acier galvanisé prelaque blanc', 'Nous proposons des tôles en acier galvanisé prélaqué de haute qualité, idéales pour les travaux de couverture, bardage, hangars, garages, entrepôts et bâtiments industriels. Caractéristiques : * ✔️ Profil : Nervisco * ✔️ Couleur : Blanc * ✔️ Épaisseur : 0,15 mm * ✔️ Largeur utile : 95 cm * ✔️ Longueur : Découpe sur mesure selon vos besoins * ✔️ Résistante à la corrosion et aux intempéries * ✔️ Vente en gros et au détail * ✔️ Stock disponible immédiatement', 'Ironwork & metalwork', 'Tôles', NULL, 50.0, 'MAD', 'm²', '100 Mètre linéaire', 'https://lechantier.ma/uploads/media/20915f58a90c.webp', $j$["https://lechantier.ma/uploads/media/20915f58a90c.webp", "https://lechantier.ma/uploads/media/a2771b7d74b8.webp"]$j$::jsonb, $j$[]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/ferronnerie-metallurgie/tole-en-acier-galvanise-prelaque-blanc", "category_fr": "Ironwork & metalwork", "supplier_matching_status": "matched", "technical_specifications_detailed": null, "technical_specifications_original": null, "specs": null}$j$::jsonb, 'https://lechantier.ma/en/produits/ferronnerie-metallurgie/tole-en-acier-galvanise-prelaque-blanc') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
