INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('eb663889-53df-525e-b889-c93026b59831'::uuid, '71b7d2d1-70ed-5051-b21e-5475e8a36ed6'::uuid, 'SIVIR FOUR ENCASTRABLE', 'Four encastrable Sivir - Inox - B66-SF2', 'Oven', NULL, NULL, 1400.0, 'MAD', 'Kilogramme', '1 Kilogramme', 'https://lechantier.ma/uploads/media/d95d30332565.webp', $j$["https://lechantier.ma/uploads/media/d95d30332565.webp"]$j$::jsonb, $j$["Mohammedia"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/four/sivir-four-encastrable", "category_fr": "Oven", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Four électrique - Puissance total:2000 W - Lampe - 8 programmes de cuisson - Panneau vitro - Minuterie automatique - Volume : 56 litres - Ventilateur tangentielle et de refroidissement - 2 plateaux émaillés +grille", "technical_specifications_original": "• Four électrique - Puissance total:2000 W - Lampe - 8 programmes de cuisson - Panneau vitro - Minuterie automatique - Volume : 56 litres - Ventilateur tangentielle et de refroidissement - 2 plateaux émaillés +grille", "specs": "• Four électrique - Puissance total:2000 W - Lampe - 8 programmes de cuisson - Panneau vitro - Minuterie automatique - Volume : 56 litres - Ventilateur tangentielle et de refroidissement - 2 plateaux émaillés +grille"}$j$::jsonb, 'https://lechantier.ma/en/produits/four/sivir-four-encastrable') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url,