INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('f5749627-54c2-5926-a982-b178e118a87d'::uuid, '91964dd3-bafc-5a0a-b8bf-cbbf65354340'::uuid, 'VERRES', 'EL WIFAQ VERRE propose Stopsol, clair, armé, imprimé, coloré et iraqui : une gamme complète de verres alliant qualité supérieure, design varié et prix compétitifs.', 'Glass supply', NULL, NULL, 43.0, 'MAD', 'm²', '1 Mètre', 'https://lechantier.ma/uploads/media/7382aa0c4d74.webp', $j$["https://lechantier.ma/uploads/media/7382aa0c4d74.webp", "https://lechantier.ma/uploads/media/be553949d77f.webp"]$j$::jsonb, $j$["Fès"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/fourniture-de-verre/verres", "category_fr": "Glass supply", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Verre Stopsol (Réfléchissant)Le verre Stopsol Maroc, aussi appelé verre réfléchissant, associe élégance et performance. Sa couche spéciale réduit la chaleur solaire et procure un effet miroir moderne, idéal pour améliorer l’efficacité énergétique des bâtiments.Avantages :Performance énergétique et isolation thermique renforcéesPersonnalisation sur mesure selon vos besoinsLivraison rapide partout au MarocÉpaisseurs disponibles : 4 mm – 6 mmApplications : Façades vitrées modernes, murs-rideaux, vitrages extérieurs avec contrôle solaire.Verre Clair (Transparent)Le verre clair Maroc, référence du vitrage transparent, offre une luminosité maximale et une clarté exceptionnelle. Disponible en découpe sur mesure avec bords polis pour une finition haut de gamme.Avantages :Transmission lumineuse optimaleUtilisation intérieure et extérieurePrix compétitifs et qualité garantieÉpaisseurs disponibles : 2 mm – 19 mmApplications : Fenêtres résidentielles et commerciales, vitrines, cloisons intérieures transparentes, garde-corps.Verre Armé (Sécurité)Le verre armé Maroc intègre un treillis métallique qui renforce la sécurité et la résistance au feu. Conforme aux normes coupe-feu marocaines, il assure une protection optimale dans les environnements à risques.Avantages :Protection contre chocs, intrusions et incendiesRobustesse et longévitéÉpaisseur disponible : 6 mmApplications : Bâtiments industriels, établissements scolaires, locaux techniques.Verre Imprimé (Décoratif)Le verre imprimé Maroc est disponible dans des gammes emblématiques telles que Jazzira, Karatatchi, MasterCarré et Mini Bouillère, permettant de personnaliser vos espaces avec élégance et originalité.Avantages :Large choix de motifs et texturesDesign décoratif adapté aux projets haut de gammeFacile à entretenir et durable dans le tempsÉpaisseurs disponibles : 3 mm – 6 mmApplications : Cloisons décoratives, parois vitrées design, panneaux signalétiques.Verre Coloré (Teinté)Le verre coloré Maroc, ou verre teinté, est disponible en plusieurs teintes : clair, bronze, gris, vert et bleu. Il apporte style et modernité aux aménagements intérieurs et extérieurs.Avantages :Large palette de couleurs et finitionsApporte une touche contemporaine aux projets architecturauxÉpaisseurs disponibles : 4 mm – 10 mmApplications : Façades architecturales colorées, mobilier design, cloisons teintées.Verre IraquiLe verre iraqui Maroc est reconnu pour ses motifs traditionnels et ses couleurs vives (bleu, rouge, vert, jaune), offrant un rendu artistique et authentique.Avantages :Design unique inspiré de l’art traditionnelFinition soignée et résistance accrueÉpaisseur disponible : 3 mmApplications : Portes intérieures décoratives, cloisons artistiques, éléments de décoration traditionnelle.", "technical_specifications_original": "• Verre Stopsol (Réfléchissant)Le verre Stopsol Maroc, aussi appelé verre réfléchissant, associe élégance et performance. Sa couche spéciale réduit la chaleur solaire et procure un effet miroir moderne, idéal pour améliorer l’efficacité énergétique des bâtiment