INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('dbec031d-ece8-5b01-b036-068ffe929018'::uuid, '91964dd3-bafc-5a0a-b8bf-cbbf65354340'::uuid, 'VERRES TREMPE', 'Le verre trempé Maroc offre une résistance 5 fois supérieure au verre classique, assurant sécurité, durabilité et élégance, avec un excellent rapport qualité-prix.', 'Glass supply', NULL, NULL, 160.0, 'MAD', 'm²', '10 Mètre', 'https://lechantier.ma/uploads/media/587ef9cb6312.webp', $j$["https://lechantier.ma/uploads/media/587ef9cb6312.webp", "https://lechantier.ma/uploads/media/a1026b4a9e1e.webp", "https://lechantier.ma/uploads/media/e57db16fba7a.webp"]$j$::jsonb, $j$["Fès"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/fourniture-de-verre/verres-trempe", "category_fr": "Glass supply", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Découvrez notre verre trempé (verre de sécurité), disponible dans toutes les grandes villes du Maroc. Résistant 5 fois plus qu’un verre classique, il offre sécurité, robustesse et élégance à prix compétitif.Caractéristiques :Épaisseurs : 4 à 20 mmCouleurs : Clair, Bronze, Gris, Bleu, VertRésistance mécanique : 120–200 MPaRésistance thermique : jusqu’à 250 °CSécurité : fragmentation non coupanteApplications :Portes, cabines de douche, garde-corps, balcons, façades, vitrines, mobilier urbain et vitrages automobiles.", "technical_specifications_original": "• Découvrez notre verre trempé (verre de sécurité), disponible dans toutes les grandes villes du Maroc. Résistant 5 fois plus qu’un verre classique, il offre sécurité, robustesse et élégance à prix compétitif.Caractéristiques :Épaisseurs : 4 à 20 mmCouleurs : Clair, Bronze, Gris, Bleu, VertRésistance mécanique : 120–200 MPaRésistance thermique : jusqu’à 250 °CSécurité : fragmentation non coupanteApplications :Portes, cabines de douche, garde-corps, balcons, façades, vitrines, mobilier urbain et vitrages automobiles.", "specs": "• Découvrez notre verre trempé (verre de sécurité), disponible dans toutes les grandes villes du Maroc. Résistant 5 fois plus qu’un verre classique, il offre sécurité, robustesse et élégance à prix compétitif.Caractéristiques :Épaisseurs : 4 à 20 mmCouleurs : Clair, Bronze, Gris, Bleu, VertRésistance mécanique : 120–200 MPaRésistance thermique : jusqu’à 250 °CSécurité : fragmentation non coupanteApplications :Portes, cabines de douche, garde-corps, balcons, façades, vitrines, mobilier urbain et vitrages automobiles."}$j$::jsonb, 'https://lechantier.ma/en/produits/fourniture-de-verre/verres-trempe') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
