INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('a54e1b9e-cab2-52b6-ae7d-b6e7edb165c5'::uuid, '58e49c12-ba77-5fc1-a698-bd6cf2b528e5'::uuid, 'Climatiseur gainable ON/OFF R410 CARRIER', 'La gamme d''unités est une solution écologique idéale pour les applications résidentielles ou Les petits commerces. Son intégration est aisée dans le faux plafond.', 'Ducted units', NULL, NULL, 8100.0, 'MAD', 'm²', '1 Pièce', 'https://lechantier.ma/uploads/media/730e5073e941.webp', $j$["https://lechantier.ma/uploads/media/730e5073e941.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/gainable/climatiseur-gainable-on-off-r410-carrier", "category_fr": "Ducted units", "supplier_matching_status": "matched", "technical_specifications_detailed": null, "technical_specifications_original": null, "specs": null}$j$::jsonb, 'https://lechantier.ma/en/produits/gainable/climatiseur-gainable-on-off-r410-carrier') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('96444a0e-4748-5745-aa29-9d03e03ee10e'::uuid, 'feab5e59-9f7f-5800-bd3e-e354e78c2fdc'::uuid, 'GAINABLE LG 12000 BTU INVERTER', 'Gainable LG INVERTER', 'Ducted units', NULL, NULL, 8600.0, 'MAD', 'Pièce', '1 Pièce', 'https://lechantier.ma/uploads/media/6686d2eb0d14.webp', $j$["https://lechantier.ma/uploads/media/6686d2eb0d14.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/gainable/gainable-lg-12000-btu-inverter", "category_fr": "Ducted units", "supplier_matching_status": "matched", "technical_specifications_detailed": "• ABNW12GL5S1.ENWTIMEPARTICULARITESLa vitesse des ventilateurs peut être modifiée à l’aide de commande filaire. Grâce à ce réglage, il est possible de modifier la vitesse de rotation du ventilateur de l’unité intérieure et d’associer la machine au réseau de gaine installé.Pompe de relevage incluse dans les Gainables H-Inverter et Inverter Basse Pression. Pompe de relevage non incluse dans les gainables Inverter Haute Pression (Accessoire ABDPG).Le niveau de nuisance sonore des unités gainables à basse pression a été considérablement réduit tout en augmentant la pression statique disponible.Les nouvelles unités gainables haute pression représentent la solution idéale pour les installations dans des petits espaces.", "technical_specifications_original": "• ABNW12GL5S1.ENWTIMEPARTICULARITESLa vitesse des ventilateurs peut être modifiée à l’aide de commande filaire. Grâce à ce réglage, il est possible de modifier la vitesse de rotation du ventilateur de l’unité intérieure et d’associer la machine au réseau de gaine installé.Pompe de relevage incluse dans les Gainables H-Inverter et Inverter Basse Pression. Pompe de relevage non incluse dans les gainables Inverter Haute Pression (Accessoire ABDPG).Le niveau de nuisance sonore des unités gainables à basse pression a été considérablement réduit tout en augmentant la pression statique disponible.Les nouvelles unités gainables haute pression représentent la solution idéale pour les installations dans des petits espaces.", "specs": "• ABNW12GL5S1.ENWTIMEPARTICULARITESLa vitesse des ventilateurs peut être modifiée à l’aide de commande filaire. Grâce à ce réglage, il est possible de modifier la vitesse de rotation du ventilateur de l’unité intérieure et d’associer la machine au réseau de gaine installé.Pompe de relevage incluse dans les Gainables H-Inverter et Inverter Basse Pression. Pompe de relevage non incluse dans les gainables Inverter Haute Pression (Accessoire ABDPG).Le niveau de nuisance sonore des unités gainables à basse pression a été considérablement réduit tout en augmentant la pression statique disponible.Les nouvelles unités gainables haute pression représentent la solution idéale pour les installations dans des petits espaces."}$j$::jsonb, 'https://lechantier.ma/en/produits/gainable/gainable-lg-12000-btu-inverter') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('f718de8c-346e-58df-ba0e-927983e96d0a'::uuid, 'feab5e59-9f7f-5800-bd3e-e354e78c2fdc'::uuid, 'GAINABLE SAMSUNG 12000 BTU INVERTER', 'GAINABLE SAMSUNG 12000 BTU INVERTER', 'Ducted units', NULL, NULL, 8399.0, 'MAD', 'Pièce', '1 Pièce', 'https://lechantier.ma/uploads/media/31ebd93ffa52.webp', $j$["https://lechantier.ma/uploads/media/31ebd93ffa52.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/gainable/gainable-samsung-12000-btu-inverter", "category_fr": "Ducted units", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Climatiseur Gainable Samsung Inverter – Performance et discrétion pour un confort sur mesureLe gainable Samsung Inverter est une solution de climatisation invisible et silencieuse, idéale pour les projets résidentiels, tertiaires ou commerciaux. Grâce à sa technologie Inverter, il assure un confort thermique optimal tout en réduisant significativement la consommation énergétique.Caractéristiques principales :Technologie Inverter : régulation automatique de la puissance pour plus d’économies et de stabilité thermiqueInstallation discrète : s’intègre dans les faux plafonds, ne laisse visibles que les grilles de soufflageSilencieux : fonctionnement ultra-silencieux, idéal pour les espaces de vie ou de travailDistribution homogène de l’air dans toutes les piècesContrôle à distance (filaire ou Wi-Fi) en option pour plus de confortAvantages : ✔️ Design invisible ✔️ Excellente efficacité énergétique (classe A ou +) ✔️ Idéal pour multi-pièces ou grandes surfaces ✔️ Compatible avec domotique et contrôle intelligentLe gainable Samsung Inverter est la solution idéale pour ceux qui recherchent confort, efficacité et esthétique.", "technical_specifications_original": "• Climatiseur G