INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('05cbbbab-f94f-59ab-bb9f-e22df1b519a4'::uuid, '80a799fe-cb3e-5be3-9e1c-b071de8fbf17'::uuid, 'Interrupteur Sectionneur interpact', 'Découvrez l''Interrupteur sectionneur Interpact de Schneider Electric.', 'Switches & sockets', NULL, NULL, 2800.0, 'MAD', 'm²', '1 Pièce', 'https://lechantier.ma/uploads/media/5b5e74978361.webp', $j$["https://lechantier.ma/uploads/media/5b5e74978361.webp"]$j$::jsonb, $j$[]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/interrupteurs-et-prises/interrupteur-sectionneur-interpact", "category_fr": "Switches & sockets", "supplier_matching_status": "matched", "technical_specifications_detailed": "• une solution fiable et robuste pour la protection et la commande des circuits électriques. Doté d'une conception haut de gamme et de fonctionnalités avancées, cet interrupteur sectionneur assure une isolation sûre et une coupure précise du courant, permettant ainsi un contrôle efficace des équipements électriques. Adapté à une variété d'applications industrielles et commerciales, l'Interrupteur sectionneur Interpact de Schneider Electric offre une performance optimale et une fiabilité exceptionnelle pour assurer la sécurité et la stabilité de vos installations électriques. Choisissez la qualité et la tranquillité d'esprit avec Schneider Electric pour vos besoins en sectionneurs électriques.", "technical_specifications_original": "• une solution fiable et robuste pour la protection et la commande des circuits électriques. Doté d'une conception haut de gamme et de fonctionnalités avancées, cet interrupteur sectionneur assure une isolation sûre et une coupure précise du courant, permettant ainsi un contrôle efficace des équipements électriques. Adapté à une variété d'applications industrielles et commerciales, l'Interrupteur sectionneur Interpact de Schneider Electric offre une performance optimale et une fiabilité exceptionnelle pour assurer la sécurité et la stabilité de vos installations électriques. Choisissez la qualité et la tranquillité d'esprit avec Schneider Electric pour vos besoins en sectionneurs électriques.", "specs": "• une solution fiable et robuste pour la protection et la commande des circuits électriques. Doté d'une conception haut de gamme et de fonctionnalités avancées, cet interrupteur sectionneur assure une isolation sûre et une coupure précise du courant, permettant ainsi un contrôle efficace des équipements électriques. Adapté à une variété d'applications industrielles et commerciales, l'Interrupteur sectionneur Interpact de Schneider Electric offre une performance optimale et une fiabilité exceptionnelle pour assurer la sécurité et la stabilité de vos installations électriques. Choisissez la qualité et la tranquillité d'esprit avec Schneider Electric pour vos besoins en sectionneurs électriques."}$j$::jsonb, 'https://lechantier.ma/en/produits/interrupteurs-et-prises/interrupteur-sectionneur-interpact') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
