INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('90d6d563-7a12-598d-8007-ed2c61c3b691'::uuid, '12cb9e66-efe1-582c-b820-841228d33eb1'::uuid, 'Bonsaï : L''art vivant en miniature', 'Bonsaï : L''art vivant en miniature Le bonsaï, véritable œuvre d''art végétale, incarne l''harmonie entre l''homme et la nature. Cette plante miniature, patiemment taillée et formée,', 'Garden', NULL, NULL, 300.0, 'MAD', 'm²', '2 Pièce', 'https://lechantier.ma/uploads/media/105d62bbbc80.webp', $j$["https://lechantier.ma/uploads/media/105d62bbbc80.webp", "https://lechantier.ma/uploads/media/bbdd251e3b68.webp", "https://lechantier.ma/uploads/media/11c709406ace.webp", "https://lechantier.ma/uploads/media/82dc11d2a739.webp", "https://lechantier.ma/uploads/media/b2bcfee145b1.webp", "https://lechantier.ma/uploads/media/b967bf3ef16f.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/jardin/bonsai-l-art-vivant-en-miniature", "category_fr": "Aménagement extérieur", "supplier_matching_status": "matched", "technical_specifications_detailed": "• 🔧 Détails techniques :1. Types de bonsaï :Intérieur : Ficus, Carmona, Serissa, Sageretia...Extérieur : Erable (Acer), Pin, Orme, Genévrier, Azalée...2. Emplacement :Intérieur : Près d'une source de lumière naturelle sans soleil direct.Extérieur : En pleine lumière, à l’abri du vent fort et du gel (selon espèce).3. Arrosage :Arrosage régulier, dès que la surface du substrat commence à sécher.Utiliser de préférence de l’eau non calcaire.Éviter les excès d’eau pour ne pas asphyxier les racines.4. Taille et entretien :Taille de formation : Permet de structurer l’arbre selon un style précis (droit, incliné, semi-cascade, etc.).Taille d’entretien : Favorise la densité et le maintien de la forme.Nettoyage des feuilles mortes et surveillance régulière contre les parasites.5. Substrat :Mélange drainant spécifique (akadama, pouzzolane, terre végétale…).Rempotage tous les 2 à 3 ans selon la croissance.6. Engrais :Engrais équilibré, spécifique bonsaï, à apporter toutes les 2 à 4 semaines en période de croissance (printemps-été).", "technical_specifications_original": "• 🔧 Détails techniques :1. Types de bonsaï :Intérieur : Ficus, Carmona, Serissa, Sageretia...Extérieur : Erable (Acer), Pin, Orme, Genévrier, Azalée...2. Emplacement :Intérieur : Près d'une source de lumière naturelle sans soleil direct.Extérieur : En pleine lumière, à l’abri du vent fort et du gel (selon espèce).3. Arrosage :Arrosage régulier, dès que la surface du substrat commence à sécher.Utiliser de préférence de l’eau non calcaire.Éviter les excès d’eau pour ne pas asphyxier les racines.4. Taille et entretien :Taille de formation : Permet de structurer l’arbre selon un style précis (droit, incliné, semi-cascade, etc.).Taille d’entretien : Favorise la densité et le maintien de la forme.Nettoyage des feuilles mortes et surveillance régulière contre les parasites.5. Substrat :Mélange drainant spécifique (akadama, pouzzolane, terre végétale…).Rempotage tous les 2 à 3 ans selon la croissance.6. Engrais :Engrais équilibré, spécifique bonsaï, à apporter toutes les 2 à 4 semaines en période de croissance (printemps-été).", "specs": "• 🔧 Détails techniques :1. Types de bonsaï :Intérieur : Ficus, Carmona, Serissa, Sageretia...Extérieur : Erable (Acer), Pin, Orme, Genévrier, Azalée...2. Emplacement :Intérieur : Près d'une source de lumière naturelle sans soleil direct.Extérieur : En pleine lumière, à l’abri du vent fort et du gel (selon espèce).3. Arrosage :Arrosage régulier, dès que la surface du substrat commence à sécher.Utiliser de préférence de l’eau non calcaire.Éviter les excès d’eau pour ne pas asphyxier les racines.4. Taille et entretien :Taille de formation : Permet de structurer l’arbre selon un style précis (droit, incliné, semi-cascade, etc.).Taille d’entretien : Favorise la densité et le maintien de la forme.Nettoyage des feuilles mortes et surveillance régulière contre les parasites.5. Substrat :Mélange drainant spécifique (akadama, pouzzolane, terre végétale…).Rempotage tous les 2 à 3 ans selon la croissance.6. Engrais :Engrais équilibré, spécifique bonsaï, à apporter toutes les 2 à 4 semaines en période de croissance (printemps-été)."}$j$::jsonb, 'https://lechantier.ma/en/produits/jardin/bonsai-l-art-vivant-en-miniature') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('d81d1e97-7b40-51e5-907b-2fff885c5ae5'::uuid, '12cb9e66-efe1-582c-b820-841228d33eb1'::uuid, 'Cactus de jardin', 'Les cactus de jardin sont des plantes succulentes exceptionnelles qui se distinguent par leur forme unique, leur résistance à la sécheresse et leur faible entretien', 'Garden', NULL, NULL, 50.0, 'MAD', 'm²', '5 Pièce', 'https://lechantier.ma/uploads/media/e7b06832362f.webp', $j$["https://lechantier.ma/uploads/media/e7b06832362f.webp", "https://lechantier.ma/uploads/media/e7778b539f45.webp", "https://lechantier.ma/uploads/media/93f3572878ab.webp", "https://lechantier.ma/uploads/media/545933f1f619.webp", "https://lechantier.ma/uploads/media/f64a2b24b4f5.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/jardin/cactus-de-jardin", "category_fr": "Aménagement extérieur", "supplier_matching_status": "matched", "technical_specifications_detailed": "• 1. Principales variétés de cactus pour le jardin :Opuntia (figuier de Barbarie – rustique jusqu’à -10°C)Echinocactus grusonii (coussin de belle-mère)Cereus peruvianus (forme colonne, très décoratif)Ferocactus (rond, épines décoratives)Trichocereus (fleurs nocturnes, port vertical)Mammillaria, Astrophytum, etc.2. Exposition :Plein soleil obligatoire 🌞Éviter les zones ombragées ou humides.", "technical_specifications_original": "• 1. Principales variétés de cactus pour le jardin :Opuntia (figuier de Barbarie – rustique jusqu’à -10°C)Echinocactus grusonii (coussin de belle-mère)Cereus peruvianus (forme colonne, très décoratif)Ferocactus (rond, épines décoratives)Trichocereus (fleurs nocturnes, port vertical)Mammillaria, Astrophytum, etc.2. Exposition :Plein soleil obligatoire 🌞Éviter les zones ombragées ou humides.", "specs": "• 1. Principales variétés de cactus pour le jardin :Opuntia (figuier de Barbarie – rustique jusqu’à -10°C)Echinocactus grusonii (coussin de belle-mère)Cereus peruvianus (forme colonne, très décoratif)Ferocactus (rond, épines décoratives)Trichocereus (fleurs nocturnes, port vertical)Mammillaria, Astrophytum, etc.2. Exposition :Plein soleil obligatoire 🌞Éviter les zones ombragées ou humides."}$j$::jsonb, 'https://lechantier.ma/en/produits/jardin/cactus-de-jardin') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('15e672f7-bfde-5203-a618-c402d5e12fa4'::uuid, '12cb9e66-efe1-582c-b820-841228d33eb1'::uuid, '🌲 Cyprès : (Cupressus sempervirens)', '🌲 Cyprès : Élégance verticale et robustesse au naturel : un conifère emblématique, apprécié pour son port élancé, son feuillage persistant et sa grande résistance.', 'Garden', NULL, NULL, 50.0, 'MAD', 'm²', '20 Pièce', 'https://lechantier.ma/uploads/media/b00dd38cd85a.webp', $j$["https://lechantier.ma/uploads/media/b00dd38cd85a.webp", "https://lechantier.ma/uploads/media/ab4c870b4dfb.webp", "https://lechantier.ma/uploads/media/6315c18d1108.webp", "https://lechantier.ma/uploads/media/8fca2a680229.webp", "https://lechantier.ma/uploads/media/885c8b6c19f1.webp", "https://lechantier.ma/uploads/media/566004f9fa87.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/jardin/cypres-cupressus-sempervirens", "category_fr": "Aménagement extérieur", "supplier_matching_status": "matched", "technical_specifications_detailed": "• 🔧 Détails techniques :1. Exposition : ☀️ Plein soleil ou mi-ombre. Le cyprès préfère les emplacements bien lumineux.2. Sol :S’adapte à de nombreux types de sols (argileux, calcaires, sablonneux) à condition qu’ils soient bien drainés.Tolère la sécheresse une fois bien établi.3. Arrosage :Arrosage régulier après plantation, surtout durant la première année.Une fois enraciné, le cyprès résiste bien à la sécheresse.4. Croissance :Rapide (notamment chez le Cyprès de Leyland : jusqu’à 1 m/an).Hauteur adulte : de 4 à 20 mètres selon la variété et les conditions.5. Taille :Peut être taillé pour former des haies denses ou des topiaires.Taille recommandée 1 à 2 fois par an, au printemps ou en fin d'été.6. Rusticité :Très rustique : résiste jusqu’à -15°C à -40°C selon les espèces.7. Utilisations :Haies occultantes ou brise-vent,Alignements en bordure,Sujet isolé pour un effet vertical et structurant.'", "technical_specifications_original": "• 🔧 Détails techniques :1. Exposition : ☀️ Plein soleil ou mi-ombre. Le cyprès préfère les emplacements bien lumineux.2. Sol :S’adapte à de nombreux types de sols (argileux, calcaires, sablonneux) à condition qu’ils soient bien drainés.Tolère la sécheresse une fois bien établi.3. Arrosage :Arrosage régulier après plantation, surtout durant la première année.Une fois enraciné, le cyprès résiste bien à la sécheresse.4. Croissance :Rapide (notamment chez le Cyprès de Leyland : jusqu’à 1 m/an).Hauteur adulte : de 4 à 20 mètres selon la variété et les conditions.5. Taille :Peut être taillé pour former des haies denses ou des topiaires.Taille recommandée 1 à 2 fois par an, au printemps ou en fin d'été.6. Rusticité :Très rustique : résiste jusqu’à -15°C à -40°C selon les espèces.7. Utilisations :Haies occultantes ou brise-vent,Alignements en bordure,Sujet isolé pour un effet vertical et structurant.'", "specs": "• 🔧 Détails techniques :1. Exposition : ☀️ Plein soleil ou mi-ombre. Le cyprès préfère les emplacements bien lumineux.2. Sol :S’adapte à de nombreux types de sols (argileux, calcaires, sablonneux) à condition qu’ils soient bien drainés.Tolère la sécheresse une fois bien établi.3. Arrosage :Arrosage régulier après plantation, surtout durant la première année.Une fois enraciné, le cyprès résiste bien à la sécheresse.4. Croissance :Rapide (notamment chez le Cyprès de Leyland : jusqu’à 1 m/an).Hauteur adulte : de 4 à 20 mètres selon la variété et les conditions.5. Taille :Peut être taillé pour former des haies denses ou des topiaires.Taille recommandée 1 à 2 fois par an, au printemps ou en fin d'été.6. Rusticité :Très rustique : résiste jusqu’à -15°C à -40°C selon les espèces.7. Utilisations :Haies occultantes ou brise-vent,Alignements en bordure,Sujet isolé pour un effet vertical et structurant.'"}$j$::jsonb, 'https://lechantier.ma/en/produits/jardin/cypres-cupressus-sempervirens') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('3cd38a27-9eda-5026-970f-b352e1f8cccb'::uuid, '12cb9e66-efe1-582c-b820-841228d33eb1'::uuid, 'dalles de jardin', 'Les dalles de jardin sont des éléments essentiels de l''aménagement extérieur . Elles permettent de créer des allées, terrasses, patios et espaces décoratifs....', 'Garden', NULL, NULL, 25.0, 'MAD', 'm²', '10 Pièce', 'https://lechantier.ma/uploads/media/fb1c4dbc191d.webp', $j$["https://lechantier.ma/uploads/media/fb1c4dbc191d.webp", "https://lechantier.ma/uploads/media/0255f72cdd34.webp", "https://lechantier.ma/uploads/media/9e5f439e6a80.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/jardin/dalles-de-jardin", "category_fr": "Aménagement extérieur", "supplier_matching_status": "matched", "technical_specifications_detailed": "• 1. Dalles en bétonTrès résistantes et durablesDisponibles en plusieurs formes et couleursEntretien facile\n• Idéales pour allées, terrasses et zones à fort passage2. Dalles en pierre naturelle(granit, ardoise, travertin, calcaire)Aspect naturel et élégantTrès bonne résistance aux intempériesChaque dalle est unique\n• Parfaites pour jardins haut de gamme3. Dalles en pierre reconstituéeMélange de pierre naturelle et liantsAspect proche de la pierre naturellePlus économiques\n• Bon compromis entre esthétique et prix4. Dalles en bois ou compositeAspect chaleureux et naturelAgréables au toucherComposite : plus résistant à l’humidité\n• Idéales pour terrasses et espaces détente5. Dalles en céramique (grès cérame)Très résistantes aux taches et au gelAntidérapantesDesign moderne\n• Parfaites pour jardins contemporainsAvantages des dalles de jardinAméliorent l’esthétique du jardinFacilitent la circulationRésistantes aux conditions climatiquesLarge choix de styles et de finitions", "technical_specifications_original": "• 1. Dalles en bétonTrès résistantes et durablesDisponibles en plusieurs formes et couleursEntretien facile\n• Idéales pour allées, terrasses et zones à fort passage2. Dalles en pierre naturelle(granit, ardoise, travertin, calcaire)Aspect naturel et élégantTrès bonne résistance aux intempériesChaque dalle est unique\n• Parfaites pour jardins haut de gamme3. Dalles en pierre reconstituéeMélange de pierre naturelle et liantsAspect proche de la pierre naturellePlus économiques\n• Bon compromis entre esthétique et prix4. Dalles en bois ou compositeAspect chaleureux et naturelAgréables au toucherComposite : plus résistant à l’humidité\n• Idéales pour terrasses et espaces détente5. Dalles en céramique (grès cérame)Très résistantes aux taches et au gelAntidérapantesDesign moderne\n• Parfaites pour jardins contemporainsAvantages des dalles de jardinAméliorent l’esthétique du jardinFacilitent la circulationRésistantes aux conditions climatiquesLarge choix de styles et de finitions", "specs": "• 1. Dalles en bétonTrès résistantes et durablesDisponibles en plusieurs formes et couleursEntretien facile\n• Idéales pour allées, terrasses et zones à fort passage2. Dalles en pierre naturelle(granit, ardoise, travertin, calcaire)Aspect naturel et élégantTrès bonne résistance aux intempériesChaque dalle est unique\n• Parfaites pour jardins haut de gamme3. Dalles en pierre reconstituéeMélange de pierre naturelle et liantsAspect proche de la pierre naturellePlus économiques\n• Bon compromis entre esthétique et prix4. Dalles en bois ou compositeAspect chaleureux et naturelAgréables au toucherComposite : plus résistant à l’humidité\n• Idéales pour terrasses et espaces détente5. Dalles en céramique (grès cérame)Très résistantes aux taches et au gelAntidérapantesDesign moderne\n• Parfaites pour jardins contemporainsAvantages des dalles de jardinAméliorent l’esthétique du jardinFacilitent la circulationRésistantes aux conditions climatiquesLarge choix de styles et de finitions"}$j$::jsonb, 'https://lechantier.ma/en/produits/jardin/dalles-de-jardin') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('8ffee442-b811-523f-b0f9-712bde540bf0'::uuid, '2b4262f7-cfbe-589e-bbe0-41b74dcbd3de'::uuid, 'FICUS NITIDA', 'FICUS NITIDA Arber persistant au feuillage dense et vert brillant ideal pour creer de l''ombre dans les espace vert et lotissements.', 'Garden', NULL, NULL, 430.0, 'MAD', 'Pièce', '100 Pièce', 'https://lechantier.ma/uploads/media/4d8238857c1d.webp', $j$["https://lechantier.ma/uploads/media/4d8238857c1d.webp", "https://lechantier.ma/uploads/media/296b3ee13ff3.webp", "https://lechantier.ma/uploads/media/be48f1cea402.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/jardin/ficus-nitida", "category_fr": "Aménagement extérieur", "supplier_matching_status": "matched", "technical_specifications_detailed": null, "technical_specifications_original": null, "specs": null}$j$::jsonb, 'https://lechantier.ma/en/produits/jardin/ficus-nitida') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('d9c58f7d-1b7d-5191-8bf8-a68ca19a2889'::uuid, '12cb9e66-efe1-582c-b820-841228d33eb1'::uuid, 'Les  Arbres en boules', 'Arbres en boules : Ficus en boules, Structure, élégance et modernité pour vos espaces verts , également appelés arbres topiaires sphériques, la taillés de manière artistique .', 'Garden', NULL, NULL, 300.0, 'MAD', 'm²', '2 Pièce', 'https://lechantier.ma/uploads/media/348df12b083c.webp', $j$["https://lechantier.ma/uploads/media/348df12b083c.webp", "https://lechantier.ma/uploads/media/117879f03211.webp", "https://lechantier.ma/uploads/media/abb88258e40d.webp", "https://lechantier.ma/uploads/media/bd47667a7f82.webp", "https://lechantier.ma/uploads/media/405c0d64fefd.webp", "https://lechantier.ma/uploads/media/f97de34b9bbf.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/jardin/les-arbres-en-boules", "category_fr": "Aménagement extérieur", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Détails techniques :1. Espèces les plus courantes :Ligustrum japonicum (Troène du Japon)Buxus sempervirens (Buis)Olea europaea (Olivier)Photinia, Pittosporum, Myrtus, Ilex crenata, etc.2. Exposition :Soleil ou mi-ombre selon l’espèce.Aime les emplacements aérés mais protégés du vent fort.3. Sol :Sol bien drainé, légèrement fertile.Tolérance variable selon les espèces à la sécheresse ou au calcaire.4. Arrosage :Arrosage régulier après plantation.En pot : surveiller le dessèchement rapide.En pleine terre : espacer les arrosages une fois la plante bien enracinée.5. Taille :Taille de formation au printemps et à la fin de l'été pour conserver la forme sphérique.Utilisation de sécateurs ou cisailles à topiaire pour un résultat net.6. Entretien :Apport d’engrais organique ou à libération lente au printemps.Paillage conseillé pour conserver l’humidité et limiter les mauvaises herbes.7. Utilisations paysagères :En pot sur terrasses, balcons ou entrées,En alignement le long d’une allée,En isolé comme point focal du jardin,En composition géométrique dans les jardins à la MAROC.", "technical_specifications_original": "• Détails techniques :1. Espèces les plus courantes :Ligustrum japonicum (Troène du Japon)Buxus sempervirens (Buis)Olea europaea (Olivier)Photinia, Pittosporum, Myrtus, Ilex crenata, etc.2. Exposition :Soleil ou mi-ombre selon l’espèce.Aime les emplacements aérés mais protégés du vent fort.3. Sol :Sol bien drainé, légèrement fertile.Tolérance variable selon les espèces à la sécheresse ou au calcaire.4. Arrosage :Arrosage régulier après plantation.En pot : surveiller le dessèchement rapide.En pleine terre : espacer les arrosages une fois la plante bien enracinée.5. Taille :Taille de formation au printemps et à la fin de l'été pour conserver la forme sphérique.Utilisation de sécateurs ou cisailles à topiaire pour un résultat net.6. Entretien :Apport d’engrais organique ou à libération lente au printemps.Paillage conseillé pour conserver l’humidité et limiter les mauvaises herbes.7. Utilisations paysagères :En pot sur terrasses, balcons ou entrées,En alignement le long d’une allée,En isolé comme point focal du jardin,En composition géométrique dans les jardins à la MAROC.", "specs": "• Détails techniques :1. Espèces les plus courantes :Ligustrum japonicum (Troène du Japon)Buxus sempervirens (Buis)Olea europaea (Olivier)Photinia, Pittosporum, Myrtus, Ilex crenata, etc.2. Exposition :Soleil ou mi-ombre selon l’espèce.Aime les emplacements aérés mais protégés du vent fort.3. Sol :Sol bien drainé, légèrement fertile.Tolérance variable selon les espèces à la sécheresse ou au calcaire.4. Arrosage :Arrosage régulier après plantation.En pot : surveiller le dessèchement rapide.En pleine terre : espacer les arrosages une fois la plante bien enracinée.5. Taille :Taille de formation au printemps et à la fin de l'été pour conserver la forme sphérique.Utilisation de sécateurs ou cisailles à topiaire pour un résultat net.6. Entretien :Apport d’engrais organique ou à libération lente au printemps.Paillage conseillé pour conserver l’humidité et limiter les mauvaises herbes.7. Utilisations paysagères :En pot sur terrasses, balcons ou entrées,En alignement le long d’une allée,En isolé comme point focal du jardin,En composition géométrique dans les jardins à la MAROC."}$j$::jsonb, 'https://lechantier.ma/en/produits/jardin/les-arbres-en-boules') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('c302d1ab-88eb-5c02-82c9-4ae4f314c902'::uuid, '12cb9e66-efe1-582c-b820-841228d33eb1'::uuid, 'Les bordures en bois', 'Les bordures en bois ; allées, pelouses, massifs de fleurs, potagers, bacs, ou zones décoratives.', 'Garden', NULL, NULL, 100.0, 'MAD', 'm²', '500 m²', 'https://lechantier.ma/uploads/media/a58b57bc9dc2.webp', $j$["https://lechantier.ma/uploads/media/a58b57bc9dc2.webp", "https://lechantier.ma/uploads/media/97e216ec3e0b.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/jardin/les-bordures-en-bois", "category_fr": "Aménagement extérieur", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Nom : Bordure en bois pour jardinType : Élément de délimitation extérieurUtilisation : Aménagement paysager – séparation entre pelouse, allée, massif, potager ou zone décorative", "technical_specifications_original": "• Nom : Bordure en bois pour jardinType : Élément de délimitation extérieurUtilisation : Aménagement paysager – séparation entre pelouse, allée, massif, potager ou zone décorative", "specs": "• Nom : Bordure en bois pour jardinType : Élément de délimitation extérieurUtilisation : Aménagement paysager – séparation entre pelouse, allée, massif, potager ou zone décorative"}$j$::jsonb, 'https://lechantier.ma/en/produits/jardin/les-bordures-en-bois') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('ec632c22-640b-56e0-8840-5e8c368eb11c'::uuid, '12cb9e66-efe1-582c-b820-841228d33eb1'::uuid, 'Les palmiers', 'Les palmiers sont des plantes ornementales majestueuses et polyvalentes, symboles d''évasion, de soleil et de sérénité. Très utilisés dans les jardins méditerranéens,', 'Garden', NULL, NULL, 400.0, 'MAD', 'm²', '3 Pièce', 'https://lechantier.ma/uploads/media/c5e776aa7631.webp', $j$["https://lechantier.ma/uploads/media/c5e776aa7631.webp", "https://lechantier.ma/uploads/media/9c07ba8b81a1.webp", "https://lechantier.ma/uploads/media/012e0203f04f.webp", "https://lechantier.ma/uploads/media/c187368c256d.webp", "https://lechantier.ma/uploads/media/f054a8d011b2.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/jardin/les-palmiers", "category_fr": "Aménagement extérieur", "supplier_matching_status": "matched", "technical_specifications_detailed": "• 1. Principales variétés disponibles :🌴 Phoenix canariensis (Palmier des Canaries)🌴 Washingtonia robusta & filifera🌴 Chamaerops humilis (Palmier nain méditerranéen)🌴 Trachycarpus fortunei (Palmier de Chine rustique)🌴 Butia capitata (Palmier pindo)🌴 Syagrus romanzoffiana (Palmier royal ou Queen palm)🌴 Livistona, Sabal, Caryota, etc.2. Exposition :Soleil à mi-ombre selon l’espèce.La plupart des palmiers aiment le plein soleil et les emplacements chauds.", "technical_specifications_original": "• 1. Principales variétés disponibles :🌴 Phoenix canariensis (Palmier des Canaries)🌴 Washingtonia robusta & filifera🌴 Chamaerops humilis (Palmier nain méditerranéen)🌴 Trachycarpus fortunei (Palmier de Chine rustique)🌴 Butia capitata (Palmier pindo)🌴 Syagrus romanzoffiana (Palmier royal ou Queen palm)🌴 Livistona, Sabal, Caryota, etc.2. Exposition :Soleil à mi-ombre selon l’espèce.La plupart des palmiers aiment le plein soleil et les emplacements chauds.", "specs": "• 1. Principales variétés disponibles :🌴 Phoenix canariensis (Palmier des Canaries)🌴 Washingtonia robusta & filifera🌴 Chamaerops humilis (Palmier nain méditerranéen)🌴 Trachycarpus fortunei (Palmier de Chine rustique)🌴 Butia capitata (Palmier pindo)🌴 Syagrus romanzoffiana (Palmier royal ou Queen palm)🌴 Livistona, Sabal, Caryota, etc.2. Exposition :Soleil à mi-ombre selon l’espèce.La plupart des palmiers aiment le plein soleil et les emplacements chauds."}$j$::jsonb, 'https://lechantier.ma/en/produits/jardin/les-palmiers') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('4cc26bb6-4936-5168-819b-67360c4fd2b3'::uuid, '12cb9e66-efe1-582c-b820-841228d33eb1'::uuid, 'les pots', 'LES POTS : Embellissez votre jardin avec style ! Facebook / Instagram', 'Garden', NULL, NULL, 25.0, 'MAD', 'm²', '2 Pièce', 'https://lechantier.ma/uploads/media/2ae7ada7ec54.webp', $j$["https://lechantier.ma/uploads/media/2ae7ada7ec54.webp", "https://lechantier.ma/uploads/media/0db7a88313cf.webp", "https://lechantier.ma/uploads/media/005234d5f0aa.webp", "https://lechantier.ma/uploads/media/74f427e638cf.webp", "https://lechantier.ma/uploads/media/1137b9d10c1c.webp", "https://lechantier.ma/uploads/media/1f829ad55d57.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/jardin/les-pots", "category_fr": "Aménagement extérieur", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Embellissez votre jardin avec style ! 🌿Donnez vie à vos plantes avec notre collection de pots de jardin de qualité supérieure :🌱 Plastique – Léger, pratique et résistant aux intempéries 🏺 Terre cuite – Authentique, naturel et idéal pour la santé des plantes ✨ Polyester – Moderne, élégant et ultra-durableQue vous ayez un balcon, une terrasse ou un grand jardin, nos pots s’adaptent à tous vos espaces et à toutes vos envies !💧 Résistants au soleil et à l’humidité 🎨 Disponibles en plusieurs tailles, formes et couleurs 🌼 Parfaits pour toutes vos plantes : fleurs, herbes, arbustes👉 Faites de votre espace vert un véritable coin de paradis !Facebook / Instagram", "technical_specifications_original": "• Embellissez votre jardin avec style ! 🌿Donnez vie à vos plantes avec notre collection de pots de jardin de qualité supérieure :🌱 Plastique – Léger, pratique et résistant aux intempéries 🏺 Terre cuite – Authentique, naturel et idéal pour la santé des plantes ✨ Polyester – Moderne, élégant et ultra-durableQue vous ayez un balcon, une terrasse ou un grand jardin, nos pots s’adaptent à tous vos espaces et à toutes vos envies !💧 Résistants au soleil et à l’humidité 🎨 Disponibles en plusieurs tailles, formes et couleurs 🌼 Parfaits pour toutes vos plantes : fleurs, herbes, arbustes👉 Faites de votre espace vert un véritable coin de paradis !Facebook / Instagram", "specs": "• Embellissez votre jardin avec style ! 🌿Donnez vie à vos plantes avec notre collection de pots de jardin de qualité supérieure :🌱 Plastique – Léger, pratique et résistant aux intempéries 🏺 Terre cuite – Authentique, naturel et idéal pour la santé des plantes ✨ Polyester – Moderne, élégant et ultra-durableQue vous ayez un balcon, une terrasse ou un grand jardin, nos pots s’adaptent à tous vos espaces et à toutes vos envies !💧 Résistants au soleil et à l’humidité 🎨 Disponibles en plusieurs tailles, formes et couleurs 🌼 Parfaits pour toutes vos plantes : fleurs, herbes, arbustes👉 Faites de votre espace vert un véritable coin de paradis !Facebook / Instagram"}$j$::jsonb, 'https://lechantier.ma/en/produits/jardin/les-pots') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('7ac1e60e-ddc9-5696-be78-12313881bce6'::uuid, '2b4262f7-cfbe-589e-bbe0-41b74dcbd3de'::uuid, 'PALMIER WASHINTONIA ROBUSTA', 'Palmier Washintonia 3m palmier décoratif . ideal pour espaces vert et lotissement. apporte une touche exotique avec peu d''entertien .', 'Garden', NULL, NULL, 450.0, 'MAD', 'Pièce', '100 Pièce', 'https://lechantier.ma/uploads/media/c1135de9468e.webp', $j$["https://lechantier.ma/uploads/media/c1135de9468e.webp", "https://lechantier.ma/uploads/media/e947ec013fd0.webp", "https://lechantier.ma/uploads/media/75df9a7e9a85.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/jardin/palmier-washintonia-robusta", "category_fr": "Aménagement extérieur", "supplier_matching_status": "matched", "technical_specifications_detailed": null, "technical_specifications_original": null, "specs": null}$j$::jsonb, 'https://lechantier.ma/en/produits/jardin/palmier-washintonia-robusta') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('80ffba1c-64fc-5b78-9fe3-b61837d9a915'::uuid, '6129b61d-8049-53d4-8837-e7bc9a8155b8'::uuid, 'Passpalum', 'Le gazon Passpalum est une variété de Gazon adaptée à tous types de climat. Résistant et dense, cette variété tolère la chaleur et l''eau salée ou des eaux usées.', 'Garden', NULL, NULL, 45.0, 'MAD', 'm²', '100 Mètre', 'https://lechantier.ma/uploads/media/650e5e22c33f.webp', $j$["https://lechantier.ma/uploads/media/650e5e22c33f.webp", "https://lechantier.ma/uploads/media/2551af157e5d.webp", "https://lechantier.ma/uploads/media/53c94da98054.webp"]$j$::jsonb, $j$[]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/jardin/passpalum", "category_fr": "Aménagement extérieur", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Le gazon Paspalum est une variété tropicale particulièrement adaptée aux climats chauds et aux sols salins. Résistant et dense, il tolère bien la sécheresse et l'eau salée, ce qui le rend idéal pour les régions côtières, les terrains de golf et les jardins soumis à des conditions difficiles.", "technical_specifications_original": "• Le gazon Paspalum est une variété tropicale particulièrement adaptée aux climats chauds et aux sols salins. Résistant et dense, il tolère bien la sécheresse et l'eau salée, ce qui le rend idéal pour les régions côtières, les terrains de golf et les jardins soumis à des conditions difficiles.", "specs": "• Le gazon Paspalum est une variété tropicale particulièrement adaptée aux climats chauds et aux sols salins. Résistant et dense, il tolère bien la sécheresse et l'eau salée, ce qui le rend idéal pour les régions côtières, les terrains de golf et les jardins soumis à des conditions difficiles."}$j$::jsonb, 'https://lechantier.ma/en/produits/jardin/passpalum') ON CONFLICT 