INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('878642c3-e11c-53e2-bdf2-c0f2780552e0'::uuid, '12cb9e66-efe1-582c-b820-841228d33eb1'::uuid, 'plantes d''intérieur', 'Plantes d''intérieur : Élégance naturelle pour vos espaces de vie : elles sont de véritables alliées pour améliorer la qualité de l''air, enrichir l''esthétique', 'Garden', NULL, NULL, 50.0, 'MAD', 'm²', '5 Pièce', 'https://lechantier.ma/uploads/media/9bcfec5fcdf2.webp', $j$["https://lechantier.ma/uploads/media/9bcfec5fcdf2.webp", "https://lechantier.ma/uploads/media/7180a13ff62d.webp", "https://lechantier.ma/uploads/media/f155db9b811a.webp", "https://lechantier.ma/uploads/media/24f93a91b222.webp", "https://lechantier.ma/uploads/media/466df2f002c2.webp", "https://lechantier.ma/uploads/media/33898c2fac52.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/jardin/plantes-d-interieur", "category_fr": "Aménagement extérieur", "supplier_matching_status": "matched", "technical_specifications_detailed": "• 🔧 Détails techniques :1. Conditions de culture :Lumière : Varie selon les espèces. Certaines nécessitent une lumière indirecte abondante (ex : Ficus lyrata), d'autres tolèrent des espaces plus ombragés (ex : Zamioculcas, Sansevieria).Température idéale : Entre 18°C et 40°C.Humidité : Préférence pour une humidité modérée à élevée. Certaines espèces tropicales bénéficient de brumisations régulières.2. Substrat et drainage :Utilisation de terreau spécial plantes vertes ou plantes d’intérieur, bien aéré.Drainage assuré par une couche de billes d’argile ou de gravier au fond du pot.3. Arrosage :Arrosage modéré : laisser sécher la surface du substrat entre deux arrosages.Fréquence ajustée selon la saison : plus régulière en été, réduite en hiver.4. Engrais :Apport d’engrais liquide tous les 15 jours en période de croissance (printemps-été).Repos végétatif en hiver : arrêt ou réduction des apports.5. Entretien courant :Nettoyage des feuilles pour enlever la poussière et favoriser la photosynthèse.Rempotage tous les 1 à 2 ans pour favoriser la croissance et le développement racinaire.", "technical_specifications_original": "• 🔧 Détails techniques :1. Conditions de culture :Lumière : Varie selon les espèces. Certaines nécessitent une lumière indirecte abondante (ex : Ficus lyrata), d'autres tolèrent des espaces plus ombragés (ex : Zamioculcas, Sansevieria).Température idéale : Entre 18°C et 40°C.Humidité : Préférence pour une humidité modérée à élevée. Certaines espèces tropicales bénéficient de brumisations régulières.2. Substrat et drainage :Utilisation de terreau spécial plantes vertes ou plantes d’intérieur, bien aéré.Drainage assuré par une couche de billes d’argile ou de gravier au fond du pot.3. Arrosage :Arrosage modéré : laisser sécher la surface du substrat entre deux arrosages.Fréquence ajustée selon la saison : plus régulière en été, réduite en hiver.4. Engrais :Apport d’engrais liquide tous les 15 jours en période de croissance (printemps-été).Repos végétatif en hiver : arrêt ou réduction des apports.5. Entretien courant :Nettoyage des feuilles pour enlever la poussière et favoriser la photosynthèse.Rempotage tous les 1 à 2 ans pour favoriser la croissance et le développement racinaire.", "specs": "• 🔧 Détails techniques :1. Conditions de culture :Lumière : Varie selon les espèces. Certaines nécessitent une lumière indirecte abondante (ex : Ficus lyrata), d'autres tolèrent des espaces plus ombragés (ex : Zamioculcas, Sansevieria).Température idéale : Entre 18°C et 40°C.Humidité : Préférence pour une humidité modérée à élevée. Certaines espèces tropicales bénéficient de brumisations régulières.2. Substrat et drainage :Utilisation de terreau spécial plantes vertes ou plantes d’intérieur, bien aéré.Drainage assuré par une couche de billes d’argile ou de gravier au fond du pot.3. Arrosage :Arrosage modéré : laisser sécher la surface du substrat entre deux arrosages.Fréquence ajustée selon la saison : plus régulière en été, réduite en hiver.4. Engrais :Apport d’engrais liquide tous les 15 jours en période de croissance (printemps-été).Repos végétatif en hiver : arrêt ou réduction des apports.5. Entretien courant :Nettoyage des feuilles pour enlever la poussière et favoriser la photosynthèse.Rempotage tous les 1 à 2 ans pour favoriser la croissance et le développement racinaire."}$j$::jsonb, 'https://lechantier.ma/en/produits/jardin/plantes-d-interieur') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
